//! Replays the golden corpus generated by
//! `electricity/scripts/generate_compose_corpus.py` -- real output from
//! Circuitry's own `core/templates.py::render_template`'s `escape`
//! parameter and `core/prompt_compose.py::render_with_composition`
//! (issue #487) -- against this crate's own
//! `compose::render_with_composition` and `electricity-template`'s own
//! no-escape render mode, each against a plain [`Value`] root.
//!
//! The same corpus's `compose_cases` are replayed a second time, against
//! a [`electricity_vm::exec::live_scope::LiveRoot`] built over a real
//! [`Store`], as an in-crate test next to `src/compose.rs`'s own unit
//! tests -- `exec::live_scope::LiveRoot` is `pub(crate)` (this crate's
//! own lazy-rendering seam, issue #463), so that replay can't live in
//! this external integration-test crate; `tests/compose_corpus.rs`'s own
//! module doc comment there names where to find it. `yield_cases` are
//! replayed there too, next to `exec::yield_`'s own unit tests, for the
//! same reason: a `yield`'s own self-reference (`{{> self}}`) needs a
//! *live* root that sees the node the same call creates, which a frozen
//! [`Value`] snapshot can never reproduce.

use electricity_template::{JsonAwareCtx, PlainCtx, ScopeRoot};
use electricity_value::{Dict, Value};
use indexmap::IndexMap;
use serde::Deserialize;
use std::collections::BTreeSet;

fn corpus() -> serde_json::Value {
    let text = std::fs::read_to_string(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/golden/compose_corpus.json"
    ))
    .expect("compose_corpus.json exists -- run electricity/scripts/generate_compose_corpus.py");
    serde_json::from_str(&text).expect("compose_corpus.json is valid JSON")
}

fn json_to_value(v: &serde_json::Value) -> Value {
    match v {
        serde_json::Value::Null => Value::None,
        serde_json::Value::Bool(b) => Value::Bool(*b),
        serde_json::Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                Value::from(i)
            } else {
                Value::Float(n.as_f64().expect("a JSON number is representable as f64"))
            }
        }
        serde_json::Value::String(s) => Value::Str(s.clone()),
        serde_json::Value::Array(items) => Value::List(items.iter().map(json_to_value).collect()),
        serde_json::Value::Object(map) => {
            let mut dict = Dict::new();
            for (k, v) in map {
                dict.insert(Value::Str(k.clone()), json_to_value(v));
            }
            Value::Dict(dict)
        }
    }
}

// ---------------------------------------------------------------------
// escape_cases: render_template(template, ctx, escape=...)
// ---------------------------------------------------------------------

#[derive(Deserialize)]
struct EscapeCase {
    template: String,
    ctx: serde_json::Value,
    label: String,
    escape: bool,
    ok: Option<String>,
    err: Option<String>,
}

#[test]
fn escape_cases_match_pythons_render_template() {
    let corpus = corpus();
    let cases: Vec<EscapeCase> =
        serde_json::from_value(corpus["escape_cases"].clone()).expect("escape_cases decode");
    assert!(!cases.is_empty());
    for case in cases {
        let root = json_to_value(&case.ctx);
        let result = electricity_template::render_template_with_root_and_escape(
            &case.template,
            &root,
            &PlainCtx,
            &case.label,
            case.escape,
        );
        match result {
            Ok(text) => assert_eq!(
                Some(text),
                case.ok,
                "template {:?} escape={} diverged (ok)",
                case.template,
                case.escape
            ),
            Err(err) => assert_eq!(
                Some(err.to_string()),
                case.err,
                "template {:?} escape={} diverged (err)",
                case.template,
                case.escape
            ),
        }
    }
}

// ---------------------------------------------------------------------
// compose_cases: render_with_composition(...), plain Value root
// ---------------------------------------------------------------------

#[derive(Deserialize)]
pub(crate) struct ComposeCase {
    pub(crate) template: String,
    pub(crate) ctx: serde_json::Value,
    pub(crate) declared: IndexMap<String, String>,
    pub(crate) known_effect_names: Vec<String>,
    pub(crate) label: String,
    pub(crate) escape: bool,
    pub(crate) json_aware: bool,
    pub(crate) ok: Option<String>,
    pub(crate) err: Option<String>,
}

fn json_aware_splice(value: &Value) -> Result<String, String> {
    electricity_json::dumps_default_str(
        value,
        electricity_json::WriteMode {
            indent: None,
            sort_keys: false,
            ensure_ascii: false,
            separators: electricity_json::Separators::Default,
        },
    )
    .map_err(|err| err.to_string())
}

fn run_compose_case<R: ScopeRoot>(
    case: &ComposeCase,
    root: &R,
    known: &BTreeSet<String>,
) -> Result<String, String> {
    if case.json_aware {
        let serializer: &dyn Fn(&Value) -> Result<String, String> = &json_aware_splice;
        let json_ctx = JsonAwareCtx::new(serializer);
        electricity_vm::compose::render_with_composition(
            &case.template,
            root,
            &case.declared,
            known,
            &case.label,
            &json_ctx,
            case.escape,
        )
    } else {
        electricity_vm::compose::render_with_composition(
            &case.template,
            root,
            &case.declared,
            known,
            &case.label,
            &PlainCtx,
            case.escape,
        )
    }
}

#[test]
fn compose_cases_match_pythons_render_with_composition() {
    let corpus = corpus();
    let cases: Vec<ComposeCase> =
        serde_json::from_value(corpus["compose_cases"].clone()).expect("compose_cases decode");
    assert!(!cases.is_empty());
    for case in &cases {
        let known: BTreeSet<String> = case.known_effect_names.iter().cloned().collect();
        let root = json_to_value(&case.ctx);
        let result = run_compose_case(case, &root, &known);
        match result {
            Ok(text) => assert_eq!(
                Some(text),
                case.ok,
                "template {:?} diverged (ok)",
                case.template
            ),
            Err(err) => assert_eq!(
                Some(err),
                case.err,
                "template {:?} diverged (err)",
                case.template
            ),
        }
    }
}
